    public function checkPermissions(array $permissions, ExternalPermissions $pagerPermissions, string $externalWiki): void {
        $this->assertArrayHasKey($externalWiki, $pagerPermissions->permissions);
        $this->assertSame(
            $this->getPermissionsByWikiId($permissions, $externalWiki),
            array_keys($pagerPermissions->permissions[$externalWiki])
        );
    }

    private function getPermissionsByWikiId(array $permissions, string $wikiId): array {
        $wikiPermissions = [];

        foreach (array_keys($permissions[$wikiId] ?? []) as $right) {
            if (count($permissions[$wikiId][$right]) === 0) {
                $wikiPermissions[] = $right;
            }
        }

        return $wikiPermissions;
    }
}
