let currentRequest = null;

async function execute(doc) {
  if (currentRequest) {
    currentRequest.abort();
  }

  const controller = new AbortController();
  currentRequest = controller.signal;

  try {
    const response = await fetch('/v1/transform/wikitext/to/lint', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ wikitext: doc.toString() }),
      signal: controller.signal,
      timeout: MAX_TIMEOUT
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const errors = await response.json();
    return errors;
  } catch (error) {
    if (error.name === 'AbortError') {
      mw.log.warn('[CodeMirror] Request aborted');
    } else {
      mw.log.warn('[CodeMirror] Error executing request:', error);
    }
    throw error;
  } finally {
    currentRequest = null;
  }
}
